import { Icon } from '@mendix/ide-ui-components/icon/Icon';
import React, { ReactElement } from 'react';
import styled from 'styled-components';
import { IconContainer, StyledInput } from './elements/formelements';

const InputWrapper = styled.div`
    position: relative;
    width: 100%;
`;

interface TextInputWithIconProps {
    ariaLabel: string;
    value: string;
    onChange?: (value: string) => void;
    placeholder?: string;
    readOnly?: boolean;
    icon?: ReactElement | string;
    validate?: () => string | undefined;
}

const TextInputWithIcon: React.FC<TextInputWithIconProps> = ({
    ariaLabel,
    value,
    onChange,
    placeholder,
    readOnly = false,
    icon,
    validate
}) => {
    return (
        <InputWrapper>
            {icon && (
                <IconContainer>
                    {typeof icon === 'string' ? (
                        <Icon src={icon} />
                    ) : (
                        icon
                    )}
                </IconContainer>
            )}
            <StyledInput
                value={value}
                placeholder={placeholder}
                isReadOnly={readOnly}
                onChange={onChange}
                aria-label={ariaLabel}
                hasIcon={!!icon}
                validate={validate}
            />
        </InputWrapper>
    );
};

export default TextInputWithIcon;
